const float ECHELLE = 3.0;

bool bx(vec2 l, float x0, float y0, float x1, float y1)
{
    return l.x >= x0 && l.x <= x1 && l.y >= y0 && l.y <= y1;
}

float distSegment(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.);
    return length(pa - ba*h);
}

vec4 pixelHeros(vec2 l, float z, float fr, float enAir, float st, float sp, float clin)
{
    vec4 c = vec4(0.);
    float face = (z > 1.5) ? 1. : 0.;
    float rebond = (enAir < .5 && (fr == 1. || fr == 3.)) ? 1. : 0.;
    vec2 u = vec2(l.x, l.y - rebond);
    float gardeVisible = (st < -.5) ? 0. : ((st < .5 || (st < 1.5 && sp < .12) || (st > 4.5 && sp > .88)) ? 1. : 0.);

    if(distSegment(u, vec2(-4., 5.), vec2(-11., 1.)) < .8) c = vec4(.35, .22, .14, .6);
    if(length(u - vec2(-11., 1.)) < 1.) c = vec4(.90, .70, .30, .6);
    if(gardeVisible > .5){
        if(bx(u, -4., 6., -4., 7.)) c = vec4(.50, .30, .20, .6);
        if(bx(u, -5., 5., -3., 5.)) c = vec4(.95, .75, .30, .6);
        if(bx(u, -4., 8., -4., 8.)) c = vec4(.95, .75, .30, .6);
    }

    float la = (enAir > .5 || fr == 0.) ? 3. : ((fr == 2.) ? -3. : 0.);
    float lb = -la;
    float jambeY0 = (enAir > .5) ? 1. : 0.;
    vec3 botte = vec3(.42, .26, .16);
    vec3 pantalon  = vec3(.22, .28, .50);
    if(bx(l, lb-1., jambeY0, lb, jambeY0+3.)) c = vec4((l.y - jambeY0 < 2.) ? botte*.8 : pantalon*.8, .8);
    if(bx(l, la-1., jambeY0, la, jambeY0+3.)) c = vec4((l.y - jambeY0 < 2.) ? botte : pantalon, .8);

    if(bx(u, -3., 4., 3., 8.)){
        vec3 tn = vec3(.20, .38, .80)*(.85 + .3*step(0., u.x));
        if(abs(u.y - 5.) < .5) tn = vec3(.62, .42, .16);
        if(abs(u.y - 5.) < .5 && abs(u.x) < .5) tn = vec3(.95, .80, .30);
        c = vec4(tn, 1.);
    }

    if(bx(u, -3., 8., 5., 11.)){
        vec3 hd = vec3(.97, .90, .78);
        if(abs(u.y - 8.) < .5) hd = vec3(.82, .72, .60);
        c = vec4(hd, 1.);
    }
    if(face > .5){
        if(clin < .5){
            if(bx(u, 0., 9., 1., 11.) || bx(u, 3., 9., 4., 11.)) c = vec4(.08, .05, .12, 1.);
            if(bx(u, 0., 11., 0., 11.) || bx(u, 3., 11., 3., 11.)) c = vec4(1.);
        } else {
            if(bx(u, 0., 9., 1., 9.) || bx(u, 3., 9., 4., 9.)) c = vec4(.08, .05, .12, 1.);
        }
        if(bx(u, -1., 9., -1., 9.) || bx(u, 5., 9., 5., 9.)) c = vec4(1., .60, .65, 1.);
        if(bx(u, 2., 8., 2., 8.)) c = vec4(.60, .25, .30, 1.);
    }

    if(gardeVisible > .5){
        if(bx(u, 3., 5., 5., 6.)) c = vec4(.70, .50, .30, .6);
    }

    vec2 cq = (u - vec2(0., 17.))/vec2(8.6, 5.6);
    if(dot(cq, cq) < 1. && u.y >= 12.){
        vec3 cp = mix(vec3(.55, .08, .25), vec3(.95, .30, .45), clamp((u.y - 12.)/10., 0., 1.));
        if(u.y < 13.) cp = vec3(.40, .06, .20);
        vec2 s1 = u - vec2(-4., 19.);
        vec2 s2 = u - vec2(3., 20.);
        vec2 s3 = u - vec2(0., 15.);
        vec2 s4 = u - vec2(6., 16.);
        if(dot(s1,s1) < 3.2 || dot(s2,s2) < 2.6 || dot(s3,s3) < 1.5 || dot(s4,s4) < 1.1) cp = vec3(.99, .95, .85);
        c = vec4(cp, .8);
    }

    if(gardeVisible < .5 && st > -.5){
        float pp = sp;
        vec2 poigne = vec2(5.5, 7.5);
        float angle = radians(35.);
        if(st < 1.5){
            poigne = mix(vec2(-4., 7.), vec2(5.5, 7.5), pp) + vec2(0., 6.*sin(pp*3.14159));
            angle = mix(radians(210.), radians(35.), pp);
        } else if(st < 2.5){
            angle = radians(35.);
        } else if(st < 3.5){
            float a1 = radians(35.);
            float a2 = radians(115.);
            float a3 = radians(-45.);
            angle = (sp < .3) ? mix(a1, a2, sp/.3) : mix(a2, a3, smoothstep(0., 1., (sp - .3)/.7));
        } else if(st < 4.5){
            angle = mix(radians(-45.), radians(35.), smoothstep(0., 1., sp));
        } else {
            pp = 1. - sp;
            poigne = mix(vec2(-4., 7.), vec2(5.5, 7.5), pp) + vec2(0., 6.*sin(pp*3.14159));
            angle = mix(radians(210.), radians(35.), pp);
        }
        vec2 direction = vec2(cos(angle), sin(angle));
        vec2 perpendiculaire = vec2(-direction.y, direction.x);
        if(distSegment(u, vec2(3., 7.), poigne) < .8) c = vec4(.80, .70, .58, .8);
        if(distSegment(u, poigne - direction*2., poigne) < .6) c = vec4(.45, .28, .18, .6);
        if(length(u - (poigne - direction*2.5)) < .8) c = vec4(.95, .75, .30, .6);
        if(distSegment(u, poigne + direction*.8 - perpendiculaire*2.2, poigne + direction*.8 + perpendiculaire*2.2) < .6) c = vec4(.95, .75, .30, .6);
        float db = distSegment(u, poigne + direction*1.5, poigne + direction*9.5);
        if(db < .75) c = vec4(mix(vec3(.62, .70, .88), vec3(.95, .97, 1.), step(db, .35)), .6);
        if(length(u - (poigne + direction*9.5)) < 1.) c = vec4(1., 1., 1., .6);
    }
    return c;
}

const int NP = 16;
const float DUREES[NP] = float[NP](2., 2., 2., 2., 2., 2., 2., 2., 2., 2., 2., 2., 2., 2.5, 7., 3.);

float alea(float n){ return fract(sin(n*91.3458)*47453.5453); }
float hash21(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233)))*43758.5453); }

vec2 mainPour(vec2 cible, vec2 pivot, float incl)
{
    if(pivot.y < .5 && abs(incl) < .35) return vec2(cible.x + floor(incl*cible.y + .5), cible.y);
    vec2 d = cible - pivot;
    float cs = cos(incl);
    float sn = sin(incl);
    return pivot + vec2(cs*d.x + sn*d.y, -sn*d.x + cs*d.y);
}

vec4 pixelEpee(vec2 u, vec2 poigne, float angle)
{
    vec4 c = vec4(0.);
    vec2 direction = vec2(cos(angle), sin(angle));
    vec2 perpendiculaire = vec2(-direction.y, direction.x);
    if(distSegment(u, poigne - direction*2., poigne) < .6) c = vec4(.45, .28, .18, 1.);
    if(length(u - (poigne - direction*2.5)) < .8) c = vec4(.95, .75, .30, 1.);
    if(distSegment(u, poigne + direction*.8 - perpendiculaire*2.2, poigne + direction*.8 + perpendiculaire*2.2) < .6) c = vec4(.95, .75, .30, 1.);
    float db = distSegment(u, poigne + direction*1.5, poigne + direction*9.5);
    if(db < .75) c = vec4(mix(vec3(.62, .70, .88), vec3(.95, .97, 1.), step(db, .35)), 1.);
    if(length(u - (poigne + direction*9.5)) < 1.) c = vec4(1.);
    return c;
}

vec4 voxelHeros(vec3 cell, vec2 fp, float sens, float cs, float sn, vec2 pivot, float incl, vec2 mainPos,
                float fr, float enAir, float st, float sp, float clin)
{
    vec2 l = cell.xy - fp;
    l.x *= sens;
    vec2 d = l - pivot;
    vec2 lr = floor(pivot + vec2(cs*d.x + sn*d.y, -sn*d.x + cs*d.y) + .5);
    if(pivot.y < .5 && abs(incl) < .35) lr = vec2(l.x + floor(incl*l.y + .5), l.y);
    if(lr.x < -14. || lr.x > 18. || lr.y < -2. || lr.y > 27.) return vec4(0.);
    vec4 c = pixelHeros(lr, cell.z, fr, enAir, st, sp, clin);
    if(st < -.5){
        if(distSegment(lr, vec2(3., 7.), mainPos) < .8) c = vec4(.80, .70, .58, .8);
        if(length(lr - mainPos) < 1.1) c = vec4(.97, .85, .72, .8);
    }
    if(c.a < .5) return vec4(0.);
    float demi = (c.a > .9) ? 2. : ((c.a > .7) ? 1. : 0.);
    if(abs(cell.z) > demi) return vec4(0.);
    return vec4(c.rgb, 1.);
}

vec4 voxelEpee(vec3 cell, vec2 piedSolCell, float sens, vec4 epee)
{
    if(abs(cell.z) > .5) return vec4(0.);
    vec2 l = cell.xy - piedSolCell;
    l.x *= sens;
    if(l.x < -16. || l.x > 26. || l.y < -4. || l.y > 40.) return vec4(0.);
    vec4 e = pixelEpee(l, epee.xy, epee.z);
    return (e.a > .5) ? vec4(e.rgb, 1.) : vec4(0.);
}

float symbole(vec2 q, float type)
{
    if(type < .5) return (bx(q, 0., 2., 1., 7.) || bx(q, 0., 0., 1., 0.)) ? 1. : 0.;
    if(type < 1.5) return (bx(q, 1., 6., 3., 6.) || bx(q, 0., 5., 0., 5.) || bx(q, 4., 5., 4., 5.) || bx(q, 4., 4., 4., 4.) || bx(q, 2., 3., 3., 3.) || bx(q, 2., 2., 2., 2.) || bx(q, 2., 0., 2., 0.)) ? 1. : 0.;
    return (bx(q, 0., 4., 3., 4.) || bx(q, 3., 3., 3., 3.) || bx(q, 2., 2., 2., 2.) || bx(q, 1., 1., 1., 1.) || bx(q, 0., 0., 3., 0.)) ? 1. : 0.;
}

vec2 projPx(vec3 w, vec3 ro, vec3 fw, vec3 rt, vec3 upv, vec2 resF, out float zc)
{
    vec3 d = w - ro;
    zc = dot(d, fw);
    vec2 q = vec2(dot(d, rt), dot(d, upv))/(max(zc, 1.)*.9);
    return floor(q*resF.y + resF*.5);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 res = vec2(96., 54.);
    vec2 resF = res*ECHELLE;
    float s = min(iResolution.x/resF.x, iResolution.y/resF.y);
    vec2 p = floor((fragCoord - .5*iResolution.xy)/s + resF*.5);
    vec2 uv = (p + .5 - resF*.5)/resF.y;

    float total = 0.;
    for(int i = 0; i < NP; i++) total += DUREES[i];
    float T = mod(iTime, total);
    float debut = 0.;
    int idx = 0;
    bool trouve = false;
    for(int i = 0; i < NP; i++){
        if(!trouve){
            if(T < debut + DUREES[i]){ idx = i; trouve = true; }
            else debut += DUREES[i];
        }
    }
    float u = T - debut;

    float sens = 1.;
    float fr = 1.;
    float enAir = 0.;
    float st = 0.;
    float sp = 0.;
    float saut = 0.;
    float decalage = 0.;
    float incl = 0.;
    vec2 pivot = vec2(0., 0.);
    vec2 cible = vec2(5.5, 7.5);
    vec4 epee = vec4(0.);
    float clin = step(mod(iTime, 2.8), .12);
    float effet = 0.;
    float fete = 0.;
    float exclam = 0.;
    float inter = 0.;
    float zzz = 0.;
    float sueur = 0.;
    vec4 planteeProche = vec4(9., 10., -1.5708, 1.);
    vec4 planteeLoin = vec4(14., 10., -1.5708, 1.);

    if(idx == 0){
        st = 2.;
        saut = step(.5, fract(iTime*1.5));
        if(u > 1.2 && u < 1.5) clin = 1.;
    } else if(idx == 1){
        float tau = fract(u/.7);
        saut = 4.*14.*tau*(1. - tau);
        enAir = saut > .5 ? 1. : 0.;
        st = 2.;
        fete = 1.;
    } else if(idx == 2){
        float tau = fract(iTime*2.);
        saut = 4.*7.*tau*(1. - tau);
        enAir = saut > .5 ? 1. : 0.;
        sens = (mod(floor(iTime*8.), 2.) < .5) ? 1. : -1.;
        st = 3.;
        sp = fract(iTime*3.);
    } else if(idx == 3){
        fr = 0.;
        st = 2.;
        effet = smoothstep(0., .4, u)*(1. - smoothstep(1.6, 2., u));
        fete = effet;
        saut = (u > 1.5) ? 2.*abs(sin((u - 1.5)*12.)) : 0.;
    } else if(idx == 4){
        float d = fract(u)*1.55 - .75;
        if(d < -.35){ st = 1.; sp = (d + .75)/.4; }
        else if(d < -.15){ st = 2.; }
        else if(d < .15){ st = 3.; sp = (d + .15)/.3; }
        else if(d < .45){ st = 4.; sp = (d - .15)/.3; }
        else { st = 5.; sp = (d - .45)/.35; }
        saut = (d > -.15 && d < .3) ? 3. : 0.;
        enAir = saut > .5 ? 1. : 0.;
    } else if(idx == 5){
        fr = (mod(floor(iTime*9.), 2.) < .5) ? 1. : 3.;
        sens = (mod(floor(iTime*1.7), 2.) < .5) ? 1. : -1.;
        decalage = floor(sin(iTime*45.)*1.5);
        clin = (mod(floor(iTime*5.), 2.) < .5) ? 1. : 0.;
        sueur = 1.;
    } else if(idx == 6){
        fr = (mod(floor(iTime*6.), 2.) < .5) ? 0. : 2.;
        sens = (mod(floor(iTime*2.), 2.) < .5) ? 1. : -1.;
        saut = floor(3.*abs(sin(iTime*6.)));
        st = 2.;
        fete = .6;
    } else if(idx == 7){
        float tau = fract(u);
        saut = 4.*18.*tau*(1. - tau);
        enAir = saut > .5 ? 1. : 0.;
        incl = 6.2832*tau;
        pivot = vec2(0., 11.);
        st = 2.;
    } else if(idx == 8){
        fr = 0.;
        st = -1.;
        incl = -.12 + .03*sin(iTime*2.);
        cible = vec2(9., 10.);
        epee = planteeProche;
        if(u > 1.2 && u < 1.5) clin = 1.;
    } else if(idx == 9){
        fr = 0.;
        st = -1.;
        epee = planteeLoin;
        cible = vec2(3.5 + 1.2*sin(iTime*14.), 13.5 + sin(iTime*11.));
        clin = step(.5, fract(iTime*2.));
        inter = 1.;
    } else if(idx == 10){
        fr = 0.;
        st = -1.;
        epee = planteeLoin;
        cible = vec2(8., 16. + 3.*sin(iTime*14.));
        fete = .4;
    } else if(idx == 11){
        fr = 0.;
        st = -1.;
        epee = planteeLoin;
        float pompe = abs(sin(u*5.));
        cible = vec2(6., 11. + 8.*pompe);
        saut = floor(2.*pompe);
        enAir = saut > .5 ? 1. : 0.;
        fete = .8;
    } else if(idx == 12){
        float tau = fract(u);
        saut = 4.*10.*tau*(1. - tau);
        enAir = saut > .5 ? 1. : 0.;
        st = 2.;
        clin = 0.;
        exclam = (u > .15) ? 1. : 0.;
    } else if(idx == 13){
        fr = 0.;
        st = -1.;
        incl = .1*sin(iTime*1.6);
        cible = vec2(9., 10.);
        epee = planteeProche;
        clin = 1.;
        zzz = 1.;
    } else if(idx == 14){
        fr = 0.;
        float tf = .326;
        vec2 sol = vec2(8., 1.2);
        if(u < 1.){
            st = 2.;
            saut = step(.5, fract(iTime*1.5));
        } else {
            st = -1.;
            float t = u - 1.;
            cible = vec2(6., 6.5);
            clin = 0.;
            if(t < tf){
                epee = vec4(5.5 + (sol.x - 5.5)*t/tf, 7.5 + 10.*t - 90.*t*t, radians(35. - 395.*t/tf), 1.);
            } else {
                float t2 = clamp((t - tf)/.25, 0., 1.);
                float rebond = (t - tf < .25) ? 12.*t2*(1. - t2) : 0.;
                epee = vec4(sol.x, sol.y + rebond, 0., 1.);
            }
            if(t > .35 && t < .9){
                float tau = (t - .35)/.55;
                saut = 36.*tau*(1. - tau);
                enAir = saut > .5 ? 1. : 0.;
            }
            if(t > .35 && t < 1.6) exclam = 1.;
            if(t >= .9 && t < 1.8){
                cible = vec2(3.5 + 1.2*sin(iTime*14.), 13.5 + sin(iTime*11.));
                clin = step(.5, fract(iTime*2.));
                if(t > 1.0) inter = 1.;
            }
            if(t >= 1.8 && t < 3.2){
                float k = smoothstep(1.8, 2.8, t);
                incl = -.7*k;
                cible = mix(vec2(3.5, 13.5), vec2(7.2, 1.2), k);
            }
            if(t >= 3.2 && t < 4.4){
                float k = smoothstep(3.2, 4.4, t);
                incl = -.7*(1. - k);
                vec2 poigne = mix(sol, vec2(5.5, 7.5), k);
                cible = poigne - vec2(.8, 0.)*(1. - k);
                epee = vec4(poigne, radians(35.)*k, 1.);
            }
            if(t >= 4.4){
                st = 2.;
                epee = vec4(0.);
                incl = 0.;
                fete = 1.;
                saut = step(.5, fract(iTime*3.))*2.;
            }
        }
    } else {
        fr = 0.;
        if(u < .35){
            st = 2.;
        } else if(u < 1.6833){
            st = -1.;
            float t = u - .35;
            cible = vec2(6., 11. + 2.*sin(iTime*10.));
            epee = vec4(5.5, 7.5 + 60.*t - 45.*t*t, radians(35.) + 6.2832*3.*t/1.3333, 1.);
        } else {
            st = 2.;
            fete = 1.;
            saut = step(.5, fract(iTime*3.))*2.;
        }
    }

    vec2 pied = vec2(48. + decalage, 12. + saut);
    vec2 piedSol = vec2(48., 12.);
    vec2 fp = floor(pied);
    vec2 mainPos = mainPour(cible, pivot, incl);
    float cs = cos(incl);
    float sn = sin(incl);

    float ang = iTime*6.2831853/12.;
    float elev = .30 + .10*sin(iTime*.5);
    float dist = 55.;
    vec3 target = vec3(48.5, 21., .5);
    vec3 ro = target + dist*vec3(sin(ang)*cos(elev), sin(elev), cos(ang)*cos(elev));
    vec3 fw = normalize(target - ro);
    vec3 rt = normalize(cross(fw, vec3(0., 1., 0.)));
    vec3 upv = cross(rt, fw);
    vec3 rd = normalize(fw + (uv.x*rt + uv.y*upv)*.9);
    rd = vec3(abs(rd.x) < 1e-4 ? 1e-4 : rd.x, abs(rd.y) < 1e-4 ? 1e-4 : rd.y, abs(rd.z) < 1e-4 ? 1e-4 : rd.z);
    vec3 inv = 1./rd;

    vec3 horizon = vec3(.16, .05, .22);
    float hh = clamp(rd.y*1.6 + .15, 0., 1.);
    vec3 col = mix(horizon, vec3(.02, .015, .08), hh);

    float fe = ECHELLE*.6;
    vec2 sc = floor(vec2(atan(rd.z, rd.x)*60.*fe, rd.y*60.*fe));
    if(hash21(sc) > 1. - .008/(fe*fe) && rd.y > .03) col += vec3(.8, .75, .9)*(.4 + .6*hash21(sc + 7.));

    if(effet > 0.){
        vec2 d = uv*res.y + vec2(0., 3.);
        float a2 = atan(d.y, d.x);
        float rayon = step(.5, fract(a2*2.5/3.14159 + iTime*.15));
        col += vec3(1., .75, .3)*.22*rayon*effet*(1. - clamp(length(d)/60., 0., 1.));
    }

    float tScene = 1e9;
    if(rd.y < 0.){
        float tSol = (12. - ro.y)*inv.y;
        tScene = tSol;
        vec3 hp = ro + rd*tSol;
        float damier = mod(floor(hp.x/8.) + floor(hp.z/8.), 2.);
        vec3 sol = vec3(.93, .2, .45)*(.55 + .25*damier);
        float lx = min(mod(hp.x, 8.), 8. - mod(hp.x, 8.));
        float lz = min(mod(hp.z, 8.), 8. - mod(hp.z, 8.));
        float ligne = smoothstep(.65, .3, min(lx, lz))*exp(-tSol*.012);
        sol = mix(sol, vec3(1., .5, .7), ligne);
        float ombre = exp(-pow(length(hp.xz - vec2(target.x, .5))/(9. - saut*.3), 2.));
        sol *= 1. - .5*ombre;
        col = mix(sol, horizon, 1. - exp(-tSol*.004));
    }

    vec3 bmin = vec3(20., 8., -3.);
    vec3 bmax = vec3(77., 56., 4.);
    vec3 t0 = (bmin - ro)*inv, t1 = (bmax - ro)*inv;
    vec3 tmn = min(t0, t1), tmx = max(t0, t1);
    float tn = max(max(tmn.x, tmn.y), tmn.z);
    float tf2 = min(min(tmx.x, tmx.y), tmx.z);

    if(tf2 > max(tn, 0.)){
        float tc = max(tn, 0.) + 1e-3;
        vec3 pos = ro + rd*tc;
        vec3 cell = floor(pos);
        vec3 stp = sign(rd);
        vec3 tDelta = abs(inv);
        vec3 tMax = (cell + max(stp, 0.) - ro)*inv;
        vec3 nrm = vec3(0., 0., 1.);
        vec2 piedSolCell = floor(piedSol);

        for(int i = 0; i < 170; i++){
            if(cell.x < bmin.x || cell.x >= bmax.x || cell.y < bmin.y || cell.y >= bmax.y || cell.z < bmin.z || cell.z >= bmax.z) break;
            if(tc > tScene) break;
            if(abs(cell.z) < 2.5){
                vec4 v = vec4(0.);
                if(epee.w > .5) v = voxelEpee(cell, piedSolCell, sens, epee);
                if(v.a < .5) v = voxelHeros(cell, fp, sens, cs, sn, pivot, incl, mainPos, fr, enAir, st, sp, clin);
                if(v.a > .5){
                    float lum = .7 + .3*dot(nrm, normalize(vec3(.35, .8, .5)));
                    col = v.rgb*lum;
                    tScene = tc;
                    break;
                }
            }
            if(tMax.x < tMax.y && tMax.x < tMax.z){
                tc = tMax.x; tMax.x += tDelta.x; cell.x += stp.x; nrm = vec3(-stp.x, 0., 0.);
            } else if(tMax.y < tMax.z){
                tc = tMax.y; tMax.y += tDelta.y; cell.y += stp.y; nrm = vec3(0., -stp.y, 0.);
            } else {
                tc = tMax.z; tMax.z += tDelta.z; cell.z += stp.z; nrm = vec3(0., 0., -stp.z);
            }
        }
    }

    float dLim = tScene*dot(rd, fw);
    float zc;
    vec2 pb;

    if(exclam > .5){
        pb = projPx(vec3(48.5, 36. + saut, .5), ro, fw, rt, upv, resF, zc);
        if(zc < dLim && symbole(floor((p - pb)/ECHELLE) + vec2(1., 0.), 0.) > .5) col = vec3(1., .9, .2);
    }
    if(inter > .5){
        pb = projPx(vec3(48.5, 36., .5), ro, fw, rt, upv, resF, zc);
        if(zc < dLim && symbole(floor((p - pb)/ECHELLE) + vec2(2., 0.), 1.) > .5) col = vec3(.9, .95, 1.);
    }
    if(zzz > .5){
        for(int i = 0; i < 3; i++){
            float ph = fract(iTime*.45 + float(i)/3.);
            pb = projPx(vec3(54. + ph*12. + float(i)*2., 30. + ph*14., .5), ro, fw, rt, upv, resF, zc);
            if(zc < dLim && ph < .9 && symbole(floor((p - pb)/ECHELLE) + vec2(1., 0.), 2.) > .5) col = vec3(.6, .8, 1.);
        }
    }
    if(sueur > .5){
        for(int i = 0; i < 3; i++){
            float ph = fract(iTime*1.3 + float(i)*.33);
            pb = projPx(vec3(40. + float(i)*8. + sin(float(i)*5.)*2., 34. - ph*20., (float(i) - 1.)*5.), ro, fw, rt, upv, resF, zc);
            if(zc < dLim && p.x >= pb.x && p.x < pb.x + ECHELLE && p.y >= pb.y && p.y < pb.y + 2.*ECHELLE) col = vec3(.5, .8, 1.);
        }
    }
    if(fete > 0.){
        for(int i = 0; i < 8; i++){
            float fi = float(i);
            float ph = fract(iTime*.9 + alea(fi));
            vec3 w = vec3(48. + (alea(fi + 3.) - .5)*44., 14. + alea(fi + 7.)*34., (alea(fi + 11.) - .5)*30.);
            pb = projPx(w, ro, fw, rt, upv, resF, zc);
            vec2 e = abs(p - pb)/ECHELLE;
            float taille = 2.*sin(ph*3.14159)*fete;
            if(zc < dLim && ((e.x < .5 && e.y < taille) || (e.y < .5 && e.x < taille)))
                col = mix(vec3(1., .95, .6), vec3(1.), step(.5, alea(fi)));
        }
    }

    fragColor = vec4(col, 1.);
}
